{
  "criteria": [
    {
      "criterion": "claridad",
      "score": 4,
      "finding": "El requisito contiene una contradicción: 'generarse automáticamente cada día' y 'solo cuando el gerente los solicite manualmente' son mutuamente excluyentes (automático vs. manual).",
      "recommendation": "Resolver la contradicción definiendo si la generación es automática con disparador temporal o manual bajo solicitud."
    },
    {
      "criterion": "especificidad",
      "score": 4,
      "finding": "No se especifica qué datos son 'los necesarios' ni el formato, alcance o nivel de detalle de los reportes de ventas.",
      "recommendation": "Definir explícitamente qué datos deben incluirse (por ejemplo: ventas totales, por producto, por tienda, etc.)."
    },
    {
      "criterion": "atomicidad",
      "score": 3,
      "finding": "El requisito mezcla dos comportamientos independientes: generación automática diaria y generación bajo solicitud manual, lo que lo hace compuesto.",
      "recommendation": "Separar en dos requisitos distintos: uno para generación automática y otro para generación bajo solicitud."
    },
    {
      "criterion": "completitud",
      "score": 4,
      "finding": "Falta definir qué datos son necesarios, el formato del reporte, el mecanismo de solicitud manual y cómo se concilia la automática diaria con la solicitud manual.",
      "recommendation": "Agregar los datos específicos que deben incluirse, el formato (PDF, Excel, etc.), y clarificar la lógica de generación."
    },
    {
      "criterion": "consistencia",
      "score": 3,
      "finding": "Contradicción interna: 'automáticamente cada día' implica ejecución sin intervención, mientras que 'solo cuando el gerente los solicite manualmente' requiere intervención humana. No pueden ocurrir simultáneamente como se plantea.",
      "recommendation": "Eliminar uno de los dos modos o definir claramente las condiciones bajo las cuales cada uno aplica (por ejemplo: automático por defecto, pero puede solicitarse manualmente fuera de horario)."
    },
    {
      "criterion": "factibilidad",
      "score": 6,
      "finding": "Es factible generar reportes automáticamente o bajo solicitud, pero la combinación actual es logicamente inviable debido a la contradicción.",
      "recommendation": "Resolver la contradicción primero; luego ambos modos son factibles individualmente."
    },
    {
      "criterion": "verificabilidad",
      "score": 4,
      "finding": "No se puede verificar objetivamente debido a la contradicción y la vaguedad de 'datos necesarios'. No hay criterios observables para confirmar cumplimiento.",
      "recommendation": "Definir datos específicos y eliminar la contradicción para permitir pruebas claras (ej: 'al solicitar manualmente, el reporte se genera en menos de 5 minutos y contiene X, Y, Z')."
    },
    {
      "criterion": "trazabilidad",
      "score": 5,
      "finding": "El requisito no tiene un identificador único (como REQ-1) ni menciona su origen (necesidad del gerente, norma, etc.), lo que dificulta su trazabilidad.",
      "recommendation": "Agregar un identificador único y vincularlo a una necesidad del stakeholder (ej: 'El gerente necesita revisar ventas diarias para tomar decisiones de reposición')."
    },
    {
      "criterion": "ausencia_ambiguedad",
      "score": 4,
      "finding": "El término 'necesarios' es subjetivo y ambiguo: no define qué datos son necesarios ni según qué criterio.",
      "recommendation": "Reemplazar 'datos necesarios' por una lista específica de campos o métricas (ej: 'ventas totales, ventas por producto, cantidad de transacciones').",
      "ambiguous_terms": [
        {
          "term": "necesarios",
          "reason": "no define qué datos son necesarios ni según qué criterio"
        }
      ]
    },
    {
      "criterion": "criterios_aceptacion",
      "score": 3,
      "finding": "No se incluyen criterios de aceptación explícitos ni condiciones medibles que permitan determinar cuándo el requisito está satisfecho.",
      "recommendation": "Agregar criterios verificables como: 'El reporte se genera en menos de 2 minutos tras solicitud manual' o 'El reporte diario automático se envía a las 08:00 horas y contiene ventas del día anterior'."
    }
  ],
  "ambiguous_terms": [
    {
      "term": "necesarios",
      "reason": "no define qué datos son necesarios ni según qué criterio"
    }
  ],
  "is_compound": true,
  "missing_information": [
    "datos específicos que deben incluirse en el reporte",
    "formato del reporte (PDF, Excel, etc.)",
    "mecanismo de solicitud manual (botón, menú, etc.)",
    "resolución de la contradicción entre generación automática y manual"
  ],
  "clarification_questions": [
    "¿Los reportes deben generarse automáticamente todos los días sin intervención, o solo cuando el gerente los solicite manualmente?",
    "¿Qué datos específicos deben incluirse en los reportes de ventas (por ejemplo: totales, por producto, por tienda, por hora)?",
    "¿En qué formato deben entregarse los reportes (PDF, Excel, CSV, etc.)?",
    "¿Cómo debe realizar el gerente la solicitud manual (por ejemplo: botón en interfaz web, menú, etc.)?"
  ],
  "summary": "El requisito presenta una contradicción crítica entre generación automática y manual, falta de especificidad en los datos y ausencia de criterios de aceptación, lo que impide su implementación y verificación claras."
}

